const {fitData} = DataScience;
const linear = NeuralNet.ACTIVATIONS.linear;
const nn = NeuralNet
.builder()
.input(1)
.layer(10)
.layer(10, NeuralNet.ACTIVATIONS.sigmoid)
.layer(1, linear)
.build();

const trainXs = NArray.range(0, 800).map(() => 10 * (2 * Math.random() - 1));
const testXs = NArray.range(0, 300).map(() => 10 * (2 * Math.random() - 1));
const sinc = x => Math.sin(x) / x;
const yf = x => sinc(x) + 0.1 * (2 * Math.random() - 1);

let {scene} = IO.plotPointCloud(trainXs.map(x => [x, yf(x)]), {color:[1,0,0]});
const {theta} = fitData(trainXs, trainXs.map(yf), nn.model, {epochs: 5000, batch: 32, learningRate: 0.1, finiteDiff: true});
nn.setWeights(theta);
IO.plotPointCloud(testXs.map(x => [x, nn.eval(x)]), {scene, color:[0,0,1]});
